ALTER TABLE users
  ADD COLUMN IF NOT EXISTS auth_id VARCHAR(255);

ALTER TABLE system_settings
  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

ALTER TABLE teaching_logs
  ADD COLUMN IF NOT EXISTS semester      VARCHAR(20),
  ADD COLUMN IF NOT EXISTS updated_at    TIMESTAMPTZ DEFAULT NOW(),
  ADD COLUMN IF NOT EXISTS head_curriculum VARCHAR(255),
  ADD COLUMN IF NOT EXISTS deputy_academic VARCHAR(255),
  ADD COLUMN IF NOT EXISTS director      VARCHAR(255);

ALTER TABLE teaching_log_images
  ADD COLUMN IF NOT EXISTS uploaded_at TIMESTAMPTZ DEFAULT NOW();

-- ─── STEP 2: TRUNCATE (order matters – children first) ──────
TRUNCATE TABLE teaching_log_images RESTART IDENTITY CASCADE;
TRUNCATE TABLE teaching_logs       RESTART IDENTITY CASCADE;
TRUNCATE TABLE users               RESTART IDENTITY CASCADE;
